#ShepherdsFarewellBerliozMIDI-RF.rb
#arranged for Sonic Pi by Robin Newman November 2018
#played by virtual midi piano, audio fed back to Sonic Pi
#as live_audio input
with_fx :reverb,amp: 3,pre_amp: 1,room: 0.8,mix: 0.6 do
  live_audio :min,stereo: true
end

#function to play midi notes/duration lists with optional transpose
define :mplay do |notes,durs,channel,tr,vel=100|
  for x in 0..notes.length-1
    if notes[x].respond_to?(:each)
      notes[x].each do |n|
        midi note(n)+tr,sustain: durs[x],channel: channel,velocity: vel
      end
    else
      midi note(notes[x])+tr,sustain: durs[x],channel: channel,velocity: vel
    end
    sleep durs[x]
  end
end
#calculates steps for midi expression value fades
define :vSlide do |start,finish,delta|
  dv=(finish-start)/20.0
   dt=delta/21.0
  21.times do |i|
    midi_cc 11,start+i*dv
    sleep dt
  end
end


use_midi_defaults port:"iac_driver_sonicpi"
midi_pc 73,channel: 1 #Flute
midi_pc 68,channel: 2 #Oboe
midi_pc 71,channel: 3 #Clarinet
midi_pc 70,channel: 4 #Bassoon
midi_pc 60,channel: 5 #French Horn
midi_pc 56,channel: 6 #Trumpet
midi_pc 57,channel: 7 #Trrombone
midi_pc 58,channel: 8 #Tuba
midi_pc 52,channel: 9 #Soprano choir Aahs
midi_pc 52,channel: 11 #Alto choir Aahs
midi_pc 52,channel: 12 #Tenor choir Aahs
midi_pc 52,channel: 13 #Bass choir Aahs
midi_pc 40,channel: 14 #Violin1
midi_pc 40,channel: 15 #Violin2
midi_pc 41,channel: 16 #Viols
midi_pc 42,channel: 17 #VCello
midi_pc 43,channel: 18 #ContraBass

#set pan values for each channel
midi_cc 10,18,channel: 1
midi_cc 10,22,channel: 2
midi_cc 10,24,channel: 3
midi_cc 10,26,channel: 4
midi_cc 10,127-30,channel: 5
midi_cc 10,127-28,channel: 6
midi_cc 10,127-26,channel: 7
midi_cc 10,60,channel: 8
midi_cc 10,30,channel: 9
midi_cc 10,60,channel: 11
midi_cc 10,127-60,channel: 12
midi_cc 10,127-30,channel: 13
midi_cc 10,50,channel: 14
midi_cc 10,70,channel: 15
midi_cc 10,127-70,channel: 16
midi_cc 10,127-30,channel: 17
midi_cc 10,68,channel: 18
use_bpm 98
#allow intial settings to settle
sleep 0.5
#channel velocity settings (adjusts balance)
vFlute =120
vOboe =125
vClarinet =70
vBassoon=100
vHorn=95
vTrumpet=95
vTrombone=95
vTuba=100
vChoir=127
vViolin1=90
vViolin2=90
vViola=85
vCello=90
vBass=110

midi_cc 11,60 #intial midi expression value (midi_cc 11)

#set midi expression (midi_cc 11 settings at various times with fades
at [45,59,78,84,120+45,120+59,120+78,120+84, 240+45,240+59,240+78,240+84 ],[[60,80,6],[80,60,1],[60,100,6],[100,60,12],  [60,80,6],[80,60,1],[60,100,6],[100,60,12], [60,80,6],[80,40,1],[40,90,6],[90,35 ,12]] do |arg|
  vSlide(arg[0],arg[1],arg[2])
end

